mapper.select:
SELECT

FROM user_info user_info


	user_info.del_flag = '0'

		AND user_info.id = #{query.id}


		AND user_info.user_code = #{query.userCode}


		AND user_info.app_type = #{query.appType}


		AND user_info.app_id = #{query.appId}


		AND user_info.phone like '%' || #{query.phone} || '%'


		and (user_info.phone like '%' || #{query.keyWord} || '%' or user_info.nick_name like '%' || #{query.keyWord} || '%' or CAST(user_info.user_code AS TEXT) like '%' || #{query.keyWord} || '%')


		AND user_info.black_flag = #{query.blackFlag}


		AND user_info.nick_name like '%' || #{query.nickName} || '%'


		AND user_info.sex = #{query.sex}


		AND user_info.country = #{query.country}


		AND COALESCE(user_info.city,
			(SELECT ua.city_name
			 FROM user_address ua
			 WHERE ua.user_id = user_info.id
			   AND ua.del_flag = '0'
			 ORDER BY CASE WHEN ua.is_default = '1' THEN 0 ELSE 1 END,
			          ua.update_time DESC,
			          ua.create_time DESC
			 LIMIT 1)
		) = #{query.city}


		AND COALESCE(user_info.province,
			(SELECT ua.province_name
			 FROM user_address ua
			 WHERE ua.user_id = user_info.id
			   AND ua.del_flag = '0'
			 ORDER BY CASE WHEN ua.is_default = '1' THEN 0 ELSE 1 END,
			          ua.update_time DESC,
			          ua.create_time DESC
			 LIMIT 1)
		) = #{query.province}
